      let write = admin || (officer && !['Settings','Audit','Accounting'].includes(resource)) || (requester && resource === 'Requisitions') || (approver && ['Requisitions','Annual Plans'].includes(resource)) || (finance && ['Invoices & 3-Way Match','Accounting'].includes(resource));
