    openModal(doc.name,`${doc.id} | ${doc.version} | ${doc.status}`,`<div class="approval-review-layout-v13"><div class="approval-document-stage-v13">${paperV13(doc,false)}</div><aside class="approval-side-v13"><section class="approval-side-card-v13"><h3>Document controls</h3><div class="approval-meta-v13"><div><span>Type</span><strong>${e13(doc.type)}</strong></div><div><span>Status</span><strong>${e13(doc.status)}</strong></div><div><span>Owner</span><strong>${e13(doc.owner)}</strong></div><div><span>Version</span><strong>${e13(doc.version)}</strong></div></div></section><section class="approval-side-card-v13"><h3>Plug-and-play template</h3><p>This document is populated from the selected transaction and can be edited, customised, versioned, sent and downloaded before the approval decision.</p></section></aside></div>`,action13('Back to approval','open-approval-v13',approvalId)+action13('Send','send-approval-doc-v13',`${approvalId}|${kind}`,'','mail')+action13('Edit / customise','edit-approval-doc-v13',`${approvalId}|${kind}`,'','document')+action13('Download PDF','download-approval-doc-v13',`${approvalId}|${kind}`,'primary','download'));
