    if(!ours.has(action)) return;
    event.preventDefault();event.stopImmediatePropagation();
    if(action==='open-approval-v6'||action==='open-approval-v13') return openApprovalV13(id);
    if(action==='preview-approval-record-v6') return previewApprovalDocumentV13(id,'main');
    if(action==='preview-approval-support-v13'||action==='preview-approval-doc-v13'){const [approvalId,kind]=id.split('|');return previewApprovalDocumentV13(approvalId,kind||'main')}
    if(action==='edit-approval-doc-v13'){const [approvalId,kind]=id.split('|');return editApprovalDocumentV13(approvalId,kind||'main')}
    if(action==='save-approval-doc-v13'){
      const parts=id.split('|'),storageKey=parts[0],approvalId=parts[1],kind=parts[2]||'main';const body=document.querySelector('#approvalDocBodyV13');if(!body)return;
      state.approvalDocumentOverridesV13[storageKey]={content:body.innerHTML,version:document.querySelector('#approvalDocVersionV13')?.value||'v1.1',status:document.querySelector('#approvalDocStatusV13')?.value||'Under review',owner:document.querySelector('#approvalDocOwnerV13')?.value||'Group Procurement',name:document.querySelector('#approvalDocTitleV13')?.value};
      const lh=state.letterhead||(state.letterhead={});lh.company=document.querySelector('#approvalDocCompanyV13')?.textContent.trim()||lh.company;lh.division=document.querySelector('#approvalDocDivisionV13')?.textContent.trim()||lh.division;lh.address=document.querySelector('#approvalDocAddressV13')?.textContent.trim()||lh.address;lh.contact=document.querySelector('#approvalDocContactV13')?.textContent.trim()||lh.contact;
      toast('Controlled version saved','The customised document remains attached to the approval record and is ready to preview, send or sign.');return previewApprovalDocumentV13(approvalId,kind)
    }
    if(action==='send-approval-doc-v13'){const [approvalId,kind]=id.split('|');return sendApprovalDocumentV13(approvalId,kind||'main')}
    if(action==='confirm-send-approval-doc-v13'){const form=document.querySelector('#sendApprovalDocFormV13');if(!form?.reportValidity())return;const [approvalId]=id.split('|');closeOverlay();return toast('Actual document sent',`${approvalBaseV13(approvalId).record} was sent with secure access and a delivery audit event.`)}
    if(action==='download-approval-doc-v13'){const [approvalId,kind]=id.split('|');const doc=(kind||'main')==='main'?approvalDocumentV13(approvalId):supportDocumentV13(approvalId,kind);return exportFile('pdf',doc.name)}
    if(action==='create-tender') return tenderModalV13();
    if(action==='add-rfx-line-v13') return document.querySelector('#rfxLinesV13')?.insertAdjacentHTML('beforeend',tenderLineRowV13(document.querySelectorAll('#rfxLinesV13 tr').length+1));
    if(action==='remove-rfx-line-v13'){const rows=document.querySelectorAll('#rfxLinesV13 tr');if(rows.length<=1)return toast('At least one line is required','A tender or RFx cannot be issued without a scope line.','warning');return el.closest('tr')?.remove()}
    if(action==='select-visible-vendors-v13'){document.querySelector('#tenderFormV13 input[name="inviteScope"][value="selected"]')?.click();visibleVendorRowsV13().forEach(row=>{const cb=row.querySelector('input');if(!cb.disabled)cb.checked=true});return updateTenderVendorUiV13()}
